pub(crate) const TEMPLATES: &[(&str, &str)] = &[
    ("aquery", "Usage: bazel aquery <options> <targets>\n\nQueries the specified targets, taking options into account and returns analysis\ntime information about the action graph.\nThe aquery command works on the post analysis phase configured target graph. It\nunderstands and takes into account configurations and configuration transitions."),
    ("build", "Usage: bazel build <options> <targets>\n\nBuilds the specified targets, using the options.\n\nSee 'bazel help target-syntax' for details and examples on how to\nspecify targets to build."),
    ("canonicalize-flags", "This command canonicalizes a list of bazel options. Don't forget to prepend  '--' to end option parsing before the flags to canonicalize. This command doesn't support the strategy policies under --invocation_policy flag."),
    ("clean", "Usage: bazel clean [<option> ...]\n\nRemoves bazel-created output, including all object files, and bazel\nmetadata.\n\nIf '--expunge' is specified, the entire working tree will be removed\nand the server stopped."),
    ("config", "Usage: bazel config <options> [<config_id> | <config_id> <config_id>]\n\nDisplays the given configuration objects, if they can be found in the Skyframe cache. The best way\nto use this command is to first run a build (or cquery), and then immediately run the config\ncommand to view the configuration. Note that any flags passed to build (or cquery) must also be\npassed to config, or else the Skyframe cache will be evicted and no configurations will be found.\n\nIf two configuration ids are passed, the difference between them will be computed and displayed,\ninstead of the entire configurations.\n\nThis command is experimental and unsupported."),
    ("coverage", "Usage: bazel coverage <options> <test-targets>\n\nBuilds and runs the specified test targets using the specified options while\ncollecting code coverage statistics. Optionally, it also generates a combined\nHTML report containing coverage results for all executed tests.\n\nThis command accepts all valid options to 'test' and 'build', and inherits\ndefaults for 'test' (and 'build') from your .bazelrc.  If you don't use\n.bazelrc, don't forget to pass all your 'build' options to 'coverage'\ntoo.\n\nSee 'bazel help target-syntax' for details and examples on how to\nspecify targets."),
    ("cquery", "Usage: bazel cquery <options> <targets>\n\nQueries the specified targets, taking options into account. Unlike query,\ncquery works on the post analysis phase configured target graph. It understands\nand takes into account configurations and configuration transitions."),
    ("dump", "Usage: bazel dump <options>\nDumps the internal state of the bazel server process.  This command is provided as an aid to debugging, not as a stable interface, so users should not try to parse the output; instead, use 'query' or 'info' for this purpose."),
    ("fetch", "Usage: bazel fetch [<option> ...]\n\n  - --all: Fetches all external dependencies, only works with bzlmod.\n  - --configure: Only fetches repositories marked as 'configure', only works with bzlmod.\n  - --repo={repo}: Only fetches the specified repository, which can be either {@apparent_repo_name} or {@@canonical_repo_name}\n, only works with bzlmod.\n  - --force: Ignore existing repository if any and force fetch the repository again, only works with bzlmod.\n  - <targets>: Fetches dependencies only for given targets."),
    ("help", "Usage: bazel help [<command>]\n\nPrints a help page for the given command, or, if no command is\nspecified, prints the index of available commands."),
    ("info", "Usage: bazel info <options> [keys]\n\nDisplays information about the state of the bazel process in the\nform of several \"key: value\" pairs.  This includes the locations of\nseveral output directories.  Because some of the\nvalues are affected by the options passed to 'bazel build', the\ninfo command accepts the same set of options.\n\nIf arguments are specified, each should be one of the keys (e.g. \"bazel-bin\").\nIn this case only the value(s) for those keys will be printed.\n\nIf --show_make_env is specified, the output includes the set of key/value\npairs in the \"Make\" environment, accessible within BUILD files.\n\nThe full list of keys and the meaning of their values is documented in\nthe bazel User Manual, and can be programmatically obtained with\n'bazel help info-keys'.\n\nSee also 'bazel version' for more detailed bazel version\ninformation."),
    ("license", "Prints the license of this software."),
    ("mobile-install", "Usage: bazel mobile-install <options> <target>\n\nInstalls a target to an Android device. Currently experimental."),
    ("mod", "Usage: bazel mod [<option> ...] tidy|<query_type> [<args> ...]\n\nWhen invoked as bazel mod tidy, the command will format the MODULE.bazel file and update all use_repo calls for supported module extensions.\nOnly works when bzlmod is enabled via --enable_bzlmod.\n\nThe command will display the external dependency graph or parts thereof, structured to display different kinds of insights depending on the query type.\n\n<query_type> [<args> ...] can be one of the following:\n\n    - graph: Displays the full dependency graph. Use the --from option to specify which module(s) you want the graph to start from (defaults to \"<root>\" which displays the whole dependency graph).\n    - deps <module>...: Displays the direct dependencies of the target module(s).\n    - path <module>...: Displays the shortest path found in the dependency graph from (any of) the --from module(s) to any of the target modules.\n    - all_paths <module>...: Displays all dependency paths from the --from modules to the target modules. To simplify the output, only the first shortest path is shown when multiple paths share the same suffix. For example, A -> B -> X would be shown, but the longer A -> C -> B -> X would be omitted. In other words, for every module Y that directly depends on the target module X, the output contains only the shortest path going through Y to reach X.\n    - explain <module>...: Prints all the places where the module is (or was) requested as a direct dependency, along with the reason why the respective final version was selected. It will display a pruned version of the `all_paths <module>...` command which only contains the direct deps of the root, the <module(s)> leaves, along with their dependants (can be modified with --depth).\n    - show_repo <module>...: Prints the rule that generated the specified repos (i.e. http_archive()). The arguments may refer to extension-generated repos.\n    - show_extension <extension>...: Prints information about the given extension(s). Usages can be filtered down to only those from modules in --extension_usage.\n    - dump_repo_mapping <canonical_repo_name>...: Prints the mappings from apparent repo names to canonical repo names for the given repos in NDJSON format. The order of entries within each JSON object is unspecified. This command is intended for use by tools such as IDEs and Starlark language servers.\n\n\n<module> arguments must be one of the following:\n\n    - \"<root>\": The current (root) module you are inside of.\n    - <name>@<version>: A specific module version.\n    - <name>@_: Specifies the empty version of a module (for modules with a non-registry override).\n    - <name>: Can be used as a placeholder for all the present versions of the module <name>.\n    - @<repo_name>: The apparent repo name of one of the root project?s direct dependencies, as it is defined in the MODULE.bazel file. Unless otherwise specified, this must refer to a module, not an extension-generated repo.\n    - @@<repo_name>: The canonical name of any repo. Unless otherwise specified, this must refer to a module, not an extension-generated repo.\n\n<extension> arguments must be of the form <module><label_to_bzl_file>%<extension_name>. For example, both rules_java//java:extensions.bzl%toolchains and @rules_java//java:extensions.bzl%toolchains are valid specifications of extensions.\n\n<canonical_repo_name> arguments are canonical repo names without any leading @ characters. The canonical repo name of the root module repository is the empty string."),
    ("print_action", "Usage: bazel print_action <options> <targets>\n\nBuilds the specified targets and prints the extra actions for the given\ntargets. Right now, the targets have to be relative paths to source files,\nand the --compile_one_dependency option has to be enabled.\n\nThis command accepts all valid options to 'build', and inherits defaults for\n'build' from your .bazelrc.  If you don't use .bazelrc, don't forget to pass\nall your 'build' options to 'print_action' too.\n\nSee 'bazel help target-syntax' for details and examples on how to\nspecify targets."),
    ("query", "Usage: bazel query <options> <query-expression>\n\nExecutes a query language expression over a specified subgraph of the\nbuild dependency graph.\n\nFor example, to show all C++ test rules in the strings package, use:\n\n  % bazel query 'kind(\"cc_.*test\", strings:*)'\n\nor to find all dependencies of //path/to/package:target, use:\n\n  % bazel query 'deps(//path/to/package:target)'\n\nor to find a dependency path between //path/to/package:target and //dependency:\n\n  % bazel query 'somepath(//path/to/package:target, //dependency)'"),
    ("run", "Usage: bazel run <options> -- <binary target> <flags to binary>\n\nBuild the specified target and run it with the given arguments.\n\n'run' accepts any 'build' options, and will inherit any defaults\nprovided by .bazelrc.\n\nIf your script needs stdin or execution not constrained by the bazel lock,\nuse 'bazel run --script_path' to write a script and then execute it."),
    ("shutdown", "This command shuts down the memory resident bazel server process."),
    ("test", "Usage: bazel test <options> <test-targets>\n\nBuilds the specified targets and runs all test targets among them (test targets\nmight also need to satisfy provided tag, size or language filters) using\nthe specified options.\n\nThis command accepts all valid options to 'build', and inherits\ndefaults for 'build' from your .bazelrc.  If you don't use .bazelrc,\ndon't forget to pass all your 'build' options to 'test' too.\n\nSee 'bazel help target-syntax' for details and examples on how to\nspecify targets."),
    ("vendor", "Usage: bazel vendor [<option> ...]\n\nDownloads external repositories into a folder specified by the flag\n--vendor_dir. Only works with bzlmod."),
    ("version", "Prints the version information that was embedded when bazel was built."),
    ("startup_options", "Startup options\n===============\n\nThese options affect how bazel starts up, or more specifically, how\nthe virtual machine hosting bazel starts up, and how the bazel server\nstarts up. These options must be specified to the left of the bazel\ncommand (e.g. 'build'), and they must not contain any space between\noption name and value.\n\nExample:\n  % bazel --host_jvm_args=-Xmx1400m --output_base=/tmp/foo build //base"),
];

/// The index (`""`), `target-syntax` and `info-keys`.
#[rustfmt::skip]
pub(crate) const PAGES: &[(&str, &str)] = &[
    ("", "Usage: bazel <command> <options> ...\n\nAvailable commands:\n  aquery              Analyzes the given targets and queries the action graph.\n  build               Builds the specified targets.\n  canonicalize-flags  Canonicalizes a list of bazel options.\n  clean               Removes output files and optionally stops the server.\n  coverage            Generates code coverage report for specified test targets.\n  cquery              Loads, analyzes, and queries the specified targets w/ configurations.\n  dump                Dumps the internal state of the bazel server process.\n  fetch               Fetches external repositories that are prerequisites to the targets.\n  help                Prints help for commands, or the index.\n  info                Displays runtime info about the bazel server.\n  license             Prints the license of this software.\n  mobile-install      Installs targets to mobile devices.\n  mod                 Queries the Bzlmod external dependency graph\n  print_action        Prints the command line args for compiling a file.\n  query               Executes a dependency graph query.\n  run                 Runs the specified target.\n  shutdown            Stops the bazel server.\n  test                Builds and runs the specified test targets.\n  vendor              Fetches external repositories into a folder specified by the flag --vendor_dir.\n  version             Prints version information for bazel.\n\nGetting more help:\n  bazel help <command>\n                   Prints help and options for <command>.\n  bazel help startup_options\n                   Options for the JVM hosting bazel.\n  bazel help target-syntax\n                   Explains the syntax for specifying targets.\n  bazel help info-keys\n                   Displays a list of keys used by the info command."),
    ("target-syntax", "Target pattern syntax\n=====================\n\nThe BUILD file label syntax is used to specify a single target. Target\npatterns generalize this syntax to sets of targets, and also support\nworking-directory-relative forms, recursion, subtraction and filtering.\nExamples:\n\nSpecifying a single target:\n\n  //foo/bar:wiz     The single target '//foo/bar:wiz'.\n  foo/bar/wiz       Equivalent to:\n                      '//foo/bar/wiz:wiz' if foo/bar/wiz is a package,\n                      '//foo/bar:wiz' if foo/bar is a package,\n                      '//foo:bar/wiz' otherwise.\n  //foo/bar         Equivalent to '//foo/bar:bar'.\n\nSpecifying all rules in a package:\n\n  //foo/bar:all       Matches all rules in package 'foo/bar'.\n\nSpecifying all rules recursively beneath a package:\n\n  //foo/...:all     Matches all rules in all packages beneath directory 'foo'.\n  //foo/...           (ditto)\n\n  By default, directory symlinks are followed when performing this recursive traversal, except\n  those that point to under the output base (for example, the convenience symlinks that are created\n  in the root directory of the workspace) But we understand that your workspace may intentionally\n  contain directories with weird symlink structures that you don't want consumed. As such, if a\n  directory has a file named\n  'DONT_FOLLOW_SYMLINKS_WHEN_TRAVERSING_THIS_DIRECTORY_VIA_A_RECURSIVE_TARGET_PATTERN'\n  then symlinks in that directory won't be followed when evaluating recursive\n  target patterns.\n\nWorking-directory relative forms:  (assume cwd = 'workspace/foo')\n\n  Target patterns which do not begin with '//' are taken relative to\n  the working directory.  Patterns which begin with '//' are always\n  absolute.\n\n  ...:all           Equivalent to  '//foo/...:all'.\n  ...                 (ditto)\n\n  bar/...:all       Equivalent to  '//foo/bar/...:all'.\n  bar/...             (ditto)\n\n  bar:wiz           Equivalent to '//foo/bar:wiz'.\n  :foo              Equivalent to '//foo:foo'.\n\n  bar               Equivalent to '//foo/bar:bar'.\n  foo/bar           Equivalent to '//foo/foo/bar:bar'.\n\n  bar:all           Equivalent to '//foo/bar:all'.\n  :all              Equivalent to '//foo:all'.\n\nSummary of target wildcards:\n\n  :all,             Match all rules in the specified packages.\n  :*, :all-targets  Match all targets (rules and files) in the specified\n                      packages, including .par and _deploy.jar files.\n\nSubtractive patterns:\n\n  Target patterns may be preceded by '-', meaning they should be\n  subtracted from the set of targets accumulated by preceding\n  patterns. (Note that this means order matters.) For example:\n\n    % bazel build -- foo/... -foo/contrib/...\n\n  builds everything in 'foo', except 'contrib'.  In case a target not\n  under 'contrib' depends on something under 'contrib' though, in order to\n  build the former bazel has to build the latter too. As usual, the '--' is\n  required to prevent '-f' from being interpreted as an option.\n\n  When running the test command, test suite expansion is applied to each target\n  pattern in sequence as the set of targets is evaluated. This means that\n  individual tests from a test suite can be excluded by a later target pattern.\n  It also means that an exclusion target pattern which matches a test suite will\n  exclude all tests which that test suite references. (Targets that would be\n  matched by the list of target patterns without any test suite expansion are\n  also built unless --build_tests_only is set.)\n\n(Use 'help --long' for full details or --short to just enumerate options.)"),
    ("info-keys", "bazel-bin               Configuration dependent directory for binaries.\nbazel-genfiles          Configuration dependent directory for generated files.\nbazel-testlogs          Configuration dependent directory for logs from a test run.\nbuild-language          A protobuffer with the build language structure\ncharacter-encoding      Information about the character encoding used by the running JVM.\nclient-env              The specifications that need to be added to the project-specific rc file to freeze the current client environment\ncommand_log             Location of the log containing the output from the build commands.\ncommitted-heap-size     The amount of memory in bytes that is committed for the Java virtual machine to use\ndefault-package-path    The default package path\ndefaults-package        Obsolete. Retained for backwards compatibility.\nexecution_root          A directory that makes all input and output files visible to the build.\ngc-count                Number of garbage collection runs.\ngc-time                 The approximate accumulated time spend on garbage collection.\ninstall_base            The installation base directory.\ninstall_md5             The logical checksum of the Blaze server.\njava-home               Location of the current Java runtime.\njava-runtime            Name and version of the current Java runtime environment.\njava-vm                 Name and version of the current Java virtual machine.\nlocal_resources         Auto detected local resources\nmax-heap-size           The maximum amount of memory in bytes that can be used for memory management.\noutput_base             A directory for shared bazel state as well as tool and strategy specific subdirectories.\noutput_path             Output directory\npackage_path            The search path for resolving package labels.\npeak-heap-size          The peak amount of used memory in bytes after any full GC during the most recent invocation.\nrelease                 bazel release identifier\nrepository_cache        The location of the repository download cache used\nserver_log              bazel server log path\nserver_pid              bazel process id\nstarlark-semantics      The effective set of Starlark semantics option values.\nused-heap-size          The amount of used memory in bytes. Note that this is not a good indicator of the actual memory use, as it includes any remaining inaccessible memory.\nused-heap-size-after-gc The amount of used memory in bytes after a call to System.gc().\nworker_metrics          persistent worker metrics\nworkspace               The working directory of the server."),
];

